<?php
defined( 'ABSPATH' ) || exit;

/** Preparación técnica para descubrimiento, comprensión y citabilidad por plataformas IA. */
class Digitalisimo_Integrations_SEO_AI {
	const OPTION = 'digitalisimo_integrations_options';
	const META = 'digitalisimo_seo_ai_';
	public static function init() {
		add_action( 'admin_menu', array( __CLASS__, 'menu' ), 30 ); add_action( 'add_meta_boxes', array( __CLASS__, 'box' ) ); add_action( 'save_post', array( __CLASS__, 'save_post' ), 25 );
		add_filter( 'robots_txt', array( __CLASS__, 'robots' ), 20, 2 ); add_filter( 'query_vars', array( __CLASS__, 'vars' ) ); add_action( 'init', array( __CLASS__, 'rewrites' ) ); add_action( 'template_redirect', array( __CLASS__, 'endpoints' ) );
		add_action( 'save_post', array( __CLASS__, 'queue_indexnow' ), 50, 3 ); add_action( 'transition_post_status', array( __CLASS__, 'indexnow_status_change' ), 20, 3 ); add_action( 'before_delete_post', array( __CLASS__, 'indexnow_delete' ), 20 ); add_action( 'digitalisimo_seo_ai_indexnow', array( __CLASS__, 'send_indexnow' ) ); add_action( 'template_redirect', array( __CLASS__, 'referral' ), 2 );
		if ( is_multisite() ) add_action( 'network_admin_menu', array( __CLASS__, 'network_menu' ) );
	}
	private static function get( $key, $default = '' ) { return Digitalisimo_Integrations_Settings::get( $key, $default ); }
	public static function crawlers() { $all = array( 'oai_search' => array( 'name' => 'OAI-SearchBot', 'ua' => 'OAI-SearchBot', 'provider' => 'OpenAI', 'category' => 'Search / Citation', 'purpose' => 'Descubrimiento y búsqueda', 'default' => 'allow', 'doc' => 'https://platform.openai.com/docs/bots' ), 'gptbot' => array( 'name' => 'GPTBot', 'ua' => 'GPTBot', 'provider' => 'OpenAI', 'category' => 'Training', 'purpose' => 'Entrenamiento', 'default' => 'disallow', 'doc' => 'https://platform.openai.com/docs/bots' ), 'perplexity' => array( 'name' => 'PerplexityBot', 'ua' => 'PerplexityBot', 'provider' => 'Perplexity', 'category' => 'Search / Citation', 'purpose' => 'Búsqueda y citación', 'default' => 'allow', 'doc' => 'https://docs.perplexity.ai/' ), 'bing' => array( 'name' => 'bingbot', 'ua' => 'bingbot', 'provider' => 'Microsoft', 'category' => 'General Search', 'purpose' => 'Búsqueda', 'default' => 'allow', 'doc' => 'https://www.bing.com/webmasters/help/which-crawlers-does-bing-use-8c184ec0' ), 'google_extended' => array( 'name' => 'Google-Extended', 'ua' => 'Google-Extended', 'provider' => 'Google', 'category' => 'Training', 'purpose' => 'Uso de contenido por IA de Google', 'default' => 'disallow', 'doc' => 'https://developers.google.com/search/docs/crawling-indexing/overview-google-crawlers' ) ); $custom = json_decode( (string) self::get( 'seo_ai_crawlers' ), true ); if ( is_array( $custom ) ) foreach ( $custom as $id => $c ) if ( ! empty( $c['ua'] ) ) $all[ sanitize_key( $id ) ] = array_merge( array( 'name' => '', 'provider' => '', 'category' => 'Custom', 'purpose' => '', 'default' => 'disallow', 'doc' => '' ), $c ); return apply_filters( 'digitalisimo_seo_ai_crawlers', $all ); }
	/** Resuelve una regla individual: sitio, red o default, incluso con "Heredar" por crawler. */
	public static function crawler_rule( $id, $crawler, &$origin = null ) { $rules = (array) json_decode( (string) self::get( 'seo_ai_crawler_rules' ), true ); $state = $rules[ $id ] ?? $crawler['default']; $info = Digitalisimo_Integrations_SEO_Resolver::option_with_origin( 'seo_ai_crawler_rules', '' ); $origin = $info['label']; if ( 'inherit' === $state && is_multisite() ) { $network = (array) get_site_option( self::OPTION, array() ); $network_rules = (array) json_decode( (string) ( $network['seo_ai_crawler_rules'] ?? '' ), true ); $state = $network_rules[ $id ] ?? $crawler['default']; $origin = 'Configuración de red'; } return in_array( $state, array( 'allow', 'disallow' ), true ) ? $state : $crawler['default']; }
	private static function setting( $id, $crawler ) { return self::crawler_rule( $id, $crawler ); }
	private static function content_paths( $field, $value ) { $cache = 'digitalisimo_seo_ai_paths_' . md5( $field . '|' . $value ); $paths = get_transient( $cache ); if ( false !== $paths ) return (array) $paths; $posts = get_posts( array( 'post_type' => get_post_types( array( 'public' => true ), 'names' ), 'post_status' => 'publish', 'posts_per_page' => -1, 'fields' => 'ids', 'meta_key' => self::META . $field, 'meta_value' => $value ) ); $paths = array(); foreach ( $posts as $id ) { $path = wp_parse_url( get_permalink( $id ), PHP_URL_PATH ); if ( $path ) $paths[] = '/' . ltrim( $path, '/' ); } $paths = array_values( array_unique( $paths ) ); set_transient( $cache, $paths, 5 * MINUTE_IN_SECONDS ); return $paths; }
	private static function clear_content_paths() { delete_transient( 'digitalisimo_seo_ai_paths_search_allow' ); delete_transient( 'digitalisimo_seo_ai_paths_search_restrict' ); delete_transient( 'digitalisimo_seo_ai_paths_training_allow' ); delete_transient( 'digitalisimo_seo_ai_paths_training_restrict' ); }
	public static function content_policy( $post_id, $field ) { $value = get_post_meta( $post_id, self::META . $field, true ); if ( in_array( $value, array( 'allow', 'restrict' ), true ) ) return $value; $categories = 'search' === $field ? array( 'Search / Citation', 'General Search' ) : array( 'Training' ); $states = array(); foreach ( self::crawlers() as $id => $crawler ) if ( in_array( $crawler['category'] ?? '', $categories, true ) ) $states[] = self::crawler_rule( $id, $crawler ); return $states && ! in_array( 'disallow', $states, true ) ? 'allow' : 'restrict'; }
	public static function robots( $output ) { if ( ! self::get( 'seo_ai_enabled', 1 ) ) return $output; $search_allow = self::content_paths( 'search', 'allow' ); $search_restrict = self::content_paths( 'search', 'restrict' ); $training_allow = self::content_paths( 'training', 'allow' ); $training_restrict = self::content_paths( 'training', 'restrict' ); foreach ( self::crawlers() as $id => $c ) { $state = self::setting( $id, $c ); $search = in_array( $c['category'] ?? '', array( 'Search / Citation', 'General Search' ), true ); $allow_paths = $search ? $search_allow : ( 'Training' === ( $c['category'] ?? '' ) ? $training_allow : array() ); $restrict_paths = $search ? $search_restrict : ( 'Training' === ( $c['category'] ?? '' ) ? $training_restrict : array() ); $output .= "\nUser-agent: " . $c['ua'] . "\n" . ( 'allow' === $state ? 'Allow: /' : 'Disallow: /' ) . "\n"; foreach ( $allow_paths as $path ) $output .= 'Allow: ' . $path . "\n"; foreach ( $restrict_paths as $path ) $output .= 'Disallow: ' . $path . "\n"; } return apply_filters( 'digitalisimo_seo_ai_robots_rules', $output ); }
	public static function menu() { add_submenu_page( null, 'SEO AI', 'SEO AI', 'manage_options', 'digitalisimo-seo-ai', array( __CLASS__, 'page' ) ); }
	public static function network_menu() { add_submenu_page( null, 'SEO AI', 'SEO AI', 'manage_network_options', 'digitalisimo-network-seo-ai', array( __CLASS__, 'page' ) ); }
	public static function page() { $network = is_network_admin(); if ( $network && ! current_user_can( 'manage_network_options' ) ) return; if ( ! $network && ! current_user_can( 'manage_options' ) ) return; $tab = sanitize_key( $_GET['tab'] ?? 'general' ); $tabs = array( 'general'=>'Resumen','crawlers'=>'Rastreadores','access'=>'Acceso y entrenamiento','entities'=>'Entidades','audit'=>'Auditoría','llms'=>'llms.txt','indexnow'=>'IndexNow','references'=>'Referencias','diagnostic'=>'Diagnóstico' ); if ( isset( $_POST['digitalisimo_ai_save'] ) && check_admin_referer( 'digitalisimo_ai_save' ) ) self::save_settings( $network ); echo '<div class="wrap digitalisimo-admin-shell"><h1>SEO AI</h1>'; if ( ! $network ) Digitalisimo_Integrations_SEO_Suite::module_navigation( 'ai' ); echo '<p>Preparación técnica para descubrimiento, comprensión y citabilidad. No garantiza aparición ni citación en plataformas de IA.</p><h2 class="nav-tab-wrapper digitalisimo-tabs">'; foreach ( $tabs as $k=>$v ) echo '<a class="nav-tab '.( $tab===$k?'nav-tab-active':'' ).'" href="'.esc_url( add_query_arg( array( 'page'=>$network?'digitalisimo-network-seo-ai':'digitalisimo-seo-ai','tab'=>$k ), $network?network_admin_url('admin.php'):admin_url('admin.php') ) ).'">'.esc_html($v).'</a>'; echo '</h2>'; if ( in_array( $tab, array('entities','audit','diagnostic','references'), true ) ) { self::report( $tab ); if ( ! $network && in_array( $tab, array( 'entities', 'audit', 'references' ), true ) ) { $tool = array( 'entities' => 'digitalisimo-seo-ai-entities', 'audit' => 'digitalisimo-seo-ai-audit', 'references' => 'digitalisimo-seo-ai-references' ); echo '<p><a class="button button-secondary" href="' . esc_url( admin_url( 'admin.php?page=' . $tool[ $tab ] ) ) . '">Abrir herramientas detalladas</a></p>'; } echo '</div>'; return; } echo '<form method="post">'; wp_nonce_field('digitalisimo_ai_save'); self::fields($tab); if ( ! $network && in_array( $tab, array( 'crawlers', 'llms', 'indexnow' ), true ) ) { $tool = array( 'crawlers' => 'digitalisimo-seo-ai-crawlers', 'llms' => 'digitalisimo-seo-ai-llms', 'indexnow' => 'digitalisimo-seo-ai-indexnow' ); echo '<p><a class="button button-secondary" href="' . esc_url( admin_url( 'admin.php?page=' . $tool[ $tab ] ) ) . '">Abrir herramientas detalladas</a>' . ( 'crawlers' === $tab ? ' <a class="button button-secondary" href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-ai-verify-crawler' ) ) . '">Verificar rastreador</a>' : '' ) . '</p>'; } submit_button('Guardar SEO AI','primary','digitalisimo_ai_save'); echo '</form></div>'; }
	private static function fields( $tab ) { if(is_multisite()){ $inherit=Digitalisimo_Integrations_SEO_Resolver::inherits_network('seo_ai_enabled');echo '<p class="notice notice-info inline"><label><input type="hidden" name="ai_inherit" value="0"><input type="checkbox" name="ai_inherit" value="1" '.checked($inherit,true,false).'> <strong>Heredar configuración SEO AI de la red</strong></label><br><span class="description">Al activar, las reglas y valores SEO AI se resuelven dinámicamente desde la red; al desactivar se personalizan en este sitio.</span></p>'; } $f=function($key,$label,$type='text',$help=''){ $v=self::get($key); echo '<p><label><strong>'.esc_html($label).'</strong><br>'; if($type==='checkbox') echo '<input type="hidden" name="ai['.esc_attr($key).']" value="0"><input type="checkbox" name="ai['.esc_attr($key).']" value="1" '.checked($v,1,false).'>'; elseif($type==='textarea') echo '<textarea class="large-text code" rows="6" name="ai['.esc_attr($key).']">'.esc_textarea($v).'</textarea>'; else echo '<input class="regular-text" type="'.esc_attr($type).'" name="ai['.esc_attr($key).']" value="'.esc_attr($v).'">'; echo '</label>'.($help?'<span class="description"> '.esc_html($help).'</span>':'').'</p>'; }; if($tab==='general'){ $f('seo_ai_enabled','SEO AI','checkbox'); echo '<div class="notice notice-info inline"><p>SEO tradicional sigue activo independientemente de este interruptor.</p></div>'; self::general_status(); } elseif($tab==='crawlers'||$tab==='access'){ echo '<table class="widefat striped"><thead><tr><th>Rastreador</th><th>Proveedor</th><th>Categoría</th><th>Regla</th><th>Origen</th></tr></thead><tbody>'; $rules=(array)json_decode((string)self::get('seo_ai_crawler_rules'),true); foreach(self::crawlers() as $id=>$c){$v=$rules[$id]??$c['default']; $origin=''; $effective=self::crawler_rule($id,$c,$origin); echo '<tr><td><strong>'.esc_html($c['name']).'</strong><br><small>'.esc_html($c['purpose']).'</small></td><td>'.esc_html($c['provider']).'</td><td>'.esc_html($c['category']).'</td><td><select name="ai_rules['.esc_attr($id).']"><option value="allow" '.selected($v,'allow',false).'>Permitir</option><option value="disallow" '.selected($v,'disallow',false).'>Bloquear</option><option value="inherit" '.selected($v,'inherit',false).'>Heredar</option></select><br><small>Valor efectivo: '.esc_html('allow'===$effective?'Permitido':'Bloqueado').'</small></td><td>'.esc_html($origin).'</td></tr>'; } echo '</tbody></table><h3>Vista previa robots.txt</h3><pre style="max-height:280px;overflow:auto">'.esc_html(self::robots('',true)).'</pre>'; } elseif($tab==='llms'){ $f('seo_ai_llms_enabled','Activar llms.txt','checkbox','Opcional; no es requisito SEO ni garantía de visibilidad.'); $f('seo_ai_llms_mode','Modo (automatic, manual o hybrid)'); $f('seo_ai_llms_urls','URLs seleccionadas','textarea','Una URL por línea.'); $f('seo_ai_llms_manual','Contenido manual','textarea'); echo '<p>Endpoint: <code>'.esc_html(home_url('/llms.txt')).'</code></p>'; } elseif($tab==='indexnow'){ $f('seo_ai_indexnow_enabled','Activar IndexNow','checkbox'); $f('seo_ai_indexnow_key','API Key'); $f('seo_ai_indexnow_auto','Envío automático','checkbox'); echo '<p>La cola se procesa en segundo plano y omite revisiones, privados y noindex.</p>'; } }
	/** Resumen de lectura; consulta exactamente las mismas reglas efectivas que robots.txt. */
	private static function general_status() {
		$search = array(); $training = array(); $rows = '';
		foreach ( self::crawlers() as $id => $crawler ) {
			$origin = ''; $rule = self::crawler_rule( $id, $crawler, $origin );
			$state = 'allow' === $rule ? 'Permitido' : 'Bloqueado';
			if ( 'Training' === ( $crawler['category'] ?? '' ) ) $training[] = $rule; elseif ( in_array( $crawler['category'] ?? '', array( 'Search / Citation', 'General Search' ), true ) ) $search[] = $rule;
			$rows .= '<tr><td><strong>' . esc_html( $crawler['name'] ) . '</strong></td><td>' . esc_html( $crawler['category'] ) . '</td><td>' . esc_html( $state ) . '</td><td>' . esc_html( $origin ) . '</td></tr>';
		}
		$search_state = $search && ! in_array( 'allow', $search, true ) ? 'Bloqueada' : 'Disponible';
		$training_state = $training && ! in_array( 'allow', $training, true ) ? 'Bloqueado' : 'Permitido parcialmente';
		$robots = file_exists( ABSPATH . 'robots.txt' ) ? 'Advertencia: archivo físico detectado' : 'Dinámico y disponible';
		echo '<h2>Estado efectivo</h2><table class="widefat striped"><tbody><tr><th>Búsqueda y citación IA</th><td>' . esc_html( $search_state ) . '</td></tr><tr><th>Entrenamiento IA</th><td>' . esc_html( $training_state ) . '</td></tr><tr><th>robots.txt</th><td>' . esc_html( $robots ) . '</td></tr><tr><th>Sitemap</th><td>' . ( self::get( 'sitemap_enabled', 1 ) ? 'Disponible' : 'Desactivado' ) . '</td></tr><tr><th>Schema</th><td>' . ( self::get( 'seo_schema_enabled', 1 ) ? 'Activo' : 'Desactivado' ) . '</td></tr><tr><th>llms.txt</th><td>' . ( self::get( 'seo_ai_llms_enabled' ) ? 'Activo' : 'Opcional, desactivado' ) . '</td></tr><tr><th>IndexNow</th><td>' . ( self::get( 'seo_ai_indexnow_enabled' ) ? 'Activo' : 'Desactivado' ) . '</td></tr></tbody></table><h2>Rastreadores IA: reglas efectivas</h2><table class="widefat striped"><thead><tr><th>Rastreador</th><th>Categoría</th><th>Valor efectivo</th><th>Origen</th></tr></thead><tbody>' . $rows . '</tbody></table><p><a class="button button-secondary" href="' . esc_url( admin_url( 'admin.php?page=digitalisimo-seo-ai&tab=crawlers' ) ) . '">Gestionar rastreadores y presets</a></p>';
	}
	private static function save_settings($network){$in=(array)wp_unslash($_POST['ai']??array());$rules=(array)wp_unslash($_POST['ai_rules']??array());$opt=$network?(array)get_site_option(self::OPTION,array()):(array)get_option(self::OPTION,array()); foreach($in as $k=>$v) if(strpos($k,'seo_ai_')===0) $opt[$k]=in_array($k,array('seo_ai_enabled','seo_ai_llms_enabled','seo_ai_indexnow_enabled','seo_ai_indexnow_auto','seo_ai_referrals_enabled'),true)?(empty($v)?0:1):sanitize_textarea_field($v); if($rules)$opt['seo_ai_crawler_rules']=wp_json_encode(array_map('sanitize_key',$rules)); if($network)update_site_option(self::OPTION,$opt); else { update_option(self::OPTION,$opt); if(is_multisite()){ $inherit=(array)get_option('digitalisimo_seo_network_inherit',array()); foreach(Digitalisimo_Integrations_Settings::defaults() as $key=>$x)if(0===strpos($key,'seo_ai_'))$inherit[$key]=empty($_POST['ai_inherit'])?0:1; update_option('digitalisimo_seo_network_inherit',$inherit,false); } } }
	public static function box(){foreach(get_post_types(array('public'=>true,'show_ui'=>true),'names') as $t)add_meta_box('digitalisimo_seo_ai','SEO AI',array(__CLASS__,'box_html'),$t,'side','default');}
	public static function box_html($p){wp_nonce_field('digitalisimo_ai_post','digitalisimo_ai_post');$a=get_post_meta($p->ID,self::META.'search',true)?:'inherit';$t=get_post_meta($p->ID,self::META.'training',true)?:'inherit';echo '<p>Estado técnico: '.(get_post_meta($p->ID,'digitalisimo_seo_noindex',true)?'Noindex':'Indexable').' · Canonical ✓ · Schema '.(self::get('seo_schema_enabled')?'✓':'—').' · Sitemap '.(self::get('sitemap_enabled')?'✓':'—').'</p><p><strong>Valor efectivo</strong><br>Búsqueda IA: '.esc_html(self::content_policy($p->ID,'search')==='allow'?'Permitida':'Restringida').' · Entrenamiento: '.esc_html(self::content_policy($p->ID,'training')==='allow'?'Permitido':'Restringido').'</p><p>Acceso IA <select name="ai_post_search"><option value="inherit" '.selected($a,'inherit',false).'>Heredar</option><option value="allow" '.selected($a,'allow',false).'>Permitir</option><option value="restrict" '.selected($a,'restrict',false).'>Restringir</option></select></p><p>Entrenamiento <select name="ai_post_training"><option value="inherit" '.selected($t,'inherit',false).'>Heredar</option><option value="allow" '.selected($t,'allow',false).'>Permitir</option><option value="restrict" '.selected($t,'restrict',false).'>Restringir</option></select></p><p class="description">Estas reglas se aplican por URL y User-Agent en el mismo robots.txt. No cambian la indexación ni añaden noindex.</p>';}
	public static function save_post($id){if(wp_is_post_revision($id)||!isset($_POST['digitalisimo_ai_post'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['digitalisimo_ai_post'])),'digitalisimo_ai_post')||!current_user_can('edit_post',$id))return;foreach(array('search','training')as$k)update_post_meta($id,self::META.$k,sanitize_key(wp_unslash($_POST['ai_post_'.$k]??'inherit')));self::clear_content_paths();}
	public static function rewrites(){add_rewrite_rule('^llms\\.txt$','index.php?digitalisimo_llms=1','top');$key=(string)self::get('seo_ai_indexnow_key');if($key)add_rewrite_rule('^'.preg_quote($key,'/').'\\.txt$','index.php?digitalisimo_indexnow_key='.rawurlencode($key),'top');}
	/** Regenera las rutas sólo al activar o cambiar la clave; nunca durante una visita pública. */
	public static function refresh_rewrites(){self::rewrites();flush_rewrite_rules();}
	public static function vars($v){$v[]='digitalisimo_llms';$v[]='digitalisimo_indexnow_key';return $v;}
	public static function endpoints(){if(get_query_var('digitalisimo_llms')){if(!self::get('seo_ai_llms_enabled'))return;status_header(200);header('Content-Type: text/plain; charset=utf-8');echo self::llms_content();exit;} $key=get_query_var('digitalisimo_indexnow_key');if($key&&hash_equals((string)self::get('seo_ai_indexnow_key'),(string)$key)){status_header(200);header('Content-Type: text/plain');echo esc_html($key);exit;}}
	public static function llms_content(){ $mode=self::get('seo_ai_llms_mode','automatic');$text='# '.(self::get('seo_site_name')?:get_bloginfo('name'))."\n\n".get_bloginfo('description')."\n";if('manual'===$mode)return self::get('seo_ai_llms_manual');foreach(array_filter(preg_split('/\r\n|\r|\n/',(string)self::get('seo_ai_llms_urls')))as$url)$text.="\n- ".$url; if('hybrid'===$mode)$text.="\n\n".self::get('seo_ai_llms_manual');return apply_filters('digitalisimo_seo_ai_llms_content',$text);}
	public static function queue_url( $url, $action, $manual = false ) { if ( ! self::get( 'seo_ai_indexnow_enabled' ) || ( ! self::get( 'seo_ai_indexnow_auto' ) && ! $manual ) || ! $url ) return; $q = (array) get_option( 'digitalisimo_seo_ai_indexnow_queue', array() ); foreach ( $q as $item ) if ( isset( $item['url'] ) && $item['url'] === $url && ( $item['action'] ?? '' ) === $action ) return; $q[] = array( 'url' => esc_url_raw( $url ), 'action' => sanitize_key( $action ), 'tries' => 0, 'not_before' => time() ); update_option( 'digitalisimo_seo_ai_indexnow_queue', $q, false ); if ( ! wp_next_scheduled( 'digitalisimo_seo_ai_indexnow' ) ) wp_schedule_single_event( time() + 30, 'digitalisimo_seo_ai_indexnow' ); }
	public static function queue_indexnow( $id, $post, $update ) { if ( wp_is_post_revision( $id ) || 'publish' !== $post->post_status || '1' === get_post_meta( $id, 'digitalisimo_seo_noindex', true ) ) return; self::queue_url( get_permalink( $id ), $update ? 'update' : 'publish' ); }
	public static function indexnow_status_change( $new, $old, $post ) { if ( wp_is_post_revision( $post->ID ) || $new === $old ) return; if ( 'publish' === $old && 'publish' !== $new ) self::queue_url( get_permalink( $post ), 'remove' ); elseif ( 'publish' === $new && 'publish' !== $old && '1' !== get_post_meta( $post->ID, 'digitalisimo_seo_noindex', true ) ) self::queue_url( get_permalink( $post ), 'publish' ); }
	public static function indexnow_delete( $id ) { $post = get_post( $id ); if ( $post && 'publish' === $post->post_status && ! wp_is_post_revision( $id ) ) self::queue_url( get_permalink( $post ), 'remove' ); }
	public static function send_indexnow(){ $queue=(array)get_option('digitalisimo_seo_ai_indexnow_queue',array());if(!$queue)return;$key=self::get('seo_ai_indexnow_key');if(!$key)return;$now=time();$ready=array();$pending=array();foreach($queue as$item){if((int)($item['not_before']??0)<=$now&&count($ready)<100)$ready[]=$item;else $pending[]=$item;}if(!$ready){$next=min(array_map(function($item){return (int)($item['not_before']??time()+60);},$pending));wp_schedule_single_event(max($now+30,$next),'digitalisimo_seo_ai_indexnow');return;}$urls=wp_list_pluck($ready,'url');$r=wp_remote_post('https://api.indexnow.org/indexnow',array('timeout'=>10,'headers'=>array('Content-Type'=>'application/json'),'body'=>wp_json_encode(array('host'=>wp_parse_url(home_url(),PHP_URL_HOST),'key'=>$key,'keyLocation'=>home_url('/'.$key.'.txt'),'urlList'=>$urls))));$status=is_wp_error($r)?0:(int)wp_remote_retrieve_response_code($r);$ok=$status>=200&&$status<300;$log=(array)get_option('digitalisimo_seo_ai_indexnow_log',array());foreach($ready as$item){$tries=(int)($item['tries']??0);if(!$ok&&($status===0||$status===429||$status>=500)&&$tries<4){$item['tries']=$tries+1;$delay=min(HOUR_IN_SECONDS,60*(2**$item['tries']));$item['not_before']=$now+$delay;$pending[]=$item;$log[]=array('url'=>$item['url'],'action'=>$item['action'],'time'=>$now,'status'=>$status,'tries'=>$item['tries'],'result'=>'reintento en '.$delay.' s');}else{$log[]=array('url'=>$item['url'],'action'=>$item['action'],'time'=>$now,'status'=>$status,'tries'=>$tries,'result'=>$ok?'enviado':'fallido');}}update_option('digitalisimo_seo_ai_indexnow_log',array_slice($log,-200),false);update_option('digitalisimo_seo_ai_indexnow_queue',$pending,false);if($pending){$next=min(array_map(function($item){return (int)($item['not_before']??time()+60);},$pending));wp_schedule_single_event(max($now+30,$next),'digitalisimo_seo_ai_indexnow');}}
	public static function referral(){if(!self::get('seo_ai_referrals_enabled')||is_admin()||empty($_SERVER['HTTP_REFERER']))return;$host=strtolower((string)wp_parse_url(esc_url_raw(wp_unslash($_SERVER['HTTP_REFERER'])),PHP_URL_HOST));$sources=class_exists('Digitalisimo_Integrations_SEO_AI_Referral_Tools')?Digitalisimo_Integrations_SEO_AI_Referral_Tools::sources():apply_filters('digitalisimo_seo_ai_referral_sources',array());foreach($sources as$domain=>$name){$domain=strtolower(trim($domain,'.'));if($host&&($host===$domain||substr($host,-strlen('.'.$domain))==='.'. $domain)){$data=(array)get_option('digitalisimo_seo_ai_referrals',array());$utm=array();foreach(array('utm_source','utm_medium','utm_campaign')as$key)if(isset($_GET[$key]))$utm[$key]=sanitize_text_field(wp_unslash($_GET[$key]));$data[]=array('source'=>$name,'page'=>home_url(add_query_arg(array(),$GLOBALS['wp']->request??'')),'utm'=>$utm,'time'=>time());update_option('digitalisimo_seo_ai_referrals',array_slice($data,-1000),false);break;}}}
	private static function report($tab){if($tab==='entities'){echo '<h2>Entidades declaradas</h2><table class="widefat"><tr><th>Organization</th><td>'.esc_html(self::get('seo_organization_name')?:get_bloginfo('name')).'</td></tr><tr><th>WebSite</th><td>'.esc_html(self::get('seo_site_name')?:get_bloginfo('name')).'</td></tr><tr><th>Ubicación</th><td>'.esc_html(self::get('seo_local_city').', '.self::get('seo_local_region').', '.self::get('seo_local_country')).'</td></tr></table><p>Se reutiliza el mismo Schema Graph del SEO nativo con IDs estables #organization, #website y #webpage.</p>';}elseif($tab==='references'){ $r=(array)get_option('digitalisimo_seo_ai_referrals',array());echo '<h2>Referencias IA</h2><p>No se guardan IPs ni conversaciones.</p><table class="widefat"><tr><th>Plataforma</th><th>Landing</th><th>Fecha</th></tr>';foreach(array_slice(array_reverse($r),0,100)as$x)echo '<tr><td>'.esc_html($x['source']).'</td><td>'.esc_html($x['page']).'</td><td>'.esc_html(date_i18n('Y-m-d H:i',$x['time'])).'</td></tr>';echo '</table>';}else{$score=0;$checks=array('Robots accesible'=>true,'Sitemap'=>self::get('sitemap_enabled'),'Schema'=>self::get('seo_schema_enabled'),'Organization'=>(bool)self::get('seo_organization_name'),'Indexable'=>(bool)get_option('blog_public'),'llms.txt'=>self::get('seo_ai_llms_enabled'),'IndexNow'=>self::get('seo_ai_indexnow_enabled'));foreach($checks as$ok)if($ok)$score+=14;$score=min(100,$score);echo '<h2>'.($tab==='audit'?'Auditoría':'Diagnóstico').' SEO AI</h2><p><strong>SEO AI Score: '.$score.'/100</strong> — '.($score>=90?'Excelente':($score>=75?'Bueno':($score>=50?'Mejorable':'Crítico'))).'</p><p class="description">Métrica técnica interna; no garantiza posicionamiento ni citación.</p><table class="widefat">';foreach($checks as$n=>$ok)echo '<tr><th>'.esc_html($n).'</th><td>'.($ok?'✓ Configurado':'⚠ Revisar').'</td></tr>';echo '</table><p>La prueba de acceso observa WordPress; un CDN/WAF puede aplicar reglas adicionales.</p>';}}
}
